14	const deleteUserBatchSize = 500
15	
16	type deleteUserMemoRef struct {
17		ID  int32
18		UID string
19	}
20	
21	type deleteUserTargetSet struct {
22		memos           []deleteUserMemoRef
23		attachments     []*store.Attachment
24		attachmentIDs   []int32
25		userSettingKeys []storepb.UserSetting_Key
26		inboxIDs        []int32
27	}
28	
29	func (d *DB) DeleteUser(ctx context.Context, delete *store.DeleteUser) (*store.DeleteUserResult, error) {
30		tx, err := d.db.BeginTx(ctx, nil)
31		if err != nil {
32			return nil, errors.Wrap(err, "failed to begin delete user transaction")
33		}
34		defer func() {
35			_ = tx.Rollback()
36		}()
37	
38		targets, err := collectDeleteUserTargets(ctx, tx, delete.ID)
39		if err != nil {
40			return nil, errors.Wrap(err, "failed to collect delete user targets")
41		}
42	
43		if err := deleteUserTargetsTx(ctx, tx, delete.ID, targets); err != nil {
44			return nil, errors.Wrap(err, "failed to delete user targets")
45		}
46	
47		if store.GetDeleteUserFailpoint(ctx) == store.DeleteUserFailpointBeforeCommit {
48			return nil, errors.New("delete user failpoint before commit")
49		}
50	
51		if err := tx.Commit(); err != nil {
52			return nil, errors.Wrap(err, "failed to commit delete user transaction")
53		}
54	
55		return &store.DeleteUserResult{
56			Attachments:     targets.attachments,
57			UserSettingKeys: targets.userSettingKeys,
58		}, nil
59	}
60	
61	func collectDeleteUserTargets(ctx context.Context, tx *sql.Tx, userID int32) (*deleteUserTargetSet, error) {
62		targets := &deleteUserTargetSet{}
63	
64		memos, err := listDeleteUserMemoTree(ctx, tx, userID)
65		if err != nil {
66			return nil, err
67		}
68		targets.memos = memos
69	
70		attachments, err := listDeleteUserAttachments(ctx, tx, userID, memoIDsFromRefs(memos))
71		if err != nil {
72			return nil, err
73		}
74		targets.attachments = attachments
75		targets.attachmentIDs = attachmentIDsFromList(attachments)
76	
77		userSettingKeys, err := listDeleteUserSettingKeys(ctx, tx, userID)
78		if err != nil {
79			return nil, err
80		}
81		targets.userSettingKeys = userSettingKeys
82	
83		inboxIDs, err := listDeleteUserInboxIDs(ctx, tx, userID, memoIDSetFromRefs(memos))
84		if err != nil {
85			return nil, err
86		}
87		targets.inboxIDs = inboxIDs
88	
89		return targets, nil
90	}
91	
92	func deleteUserTargetsTx(ctx context.Context, tx *sql.Tx, userID int32, targets *deleteUserTargetSet) error {
93		memoIDs := memoIDsFromRefs(targets.memos)
94		contentIDs := memoContentIDsFromRefs(targets.memos)
95	
96		if err := deleteReactionsByContentIDsTx(ctx, tx, contentIDs); err != nil {
97			return err
98		}
99		if err := deleteAttachmentsByIDsTx(ctx, tx, targets.attachmentIDs); err != nil {
100			return err
101		}
102		if err := deleteReactionsByCreatorTx(ctx, tx, userID); err != nil {
103			return err
104		}
105		if err := deleteMemoSharesTx(ctx, tx, userID, memoIDs); err != nil {
106			return err
107		}
108		if err := deleteInboxesByIDsTx(ctx, tx, targets.inboxIDs); err != nil {
109			return err
110		}
111		if err := deleteUserIdentitiesTx(ctx, tx, userID); err != nil {
112			return err
113		}
114		if err := deleteUserSettingsTx(ctx, tx, userID); err != nil {
115			return err
116		}
117		if err := deleteMemoRelationsTx(ctx, tx, memoIDs); err != nil {
118			return err
119		}
120		if err := deleteMemosTx(ctx, tx, memoIDs); err != nil {
121			return err
122		}
123		if err := deleteUserRowTx(ctx, tx, userID); err != nil {
124			return err
125		}
126		return nil
127	}
128	
129	func listDeleteUserMemoTree(ctx context.Context, tx *sql.Tx, userID int32) ([]deleteUserMemoRef, error) {
130		return listDeleteUserMemoTreeIterative(ctx, tx, userID)
131	}
132	
133	func listDeleteUserMemoTreeIterative(ctx context.Context, tx *sql.Tx, userID int32) ([]deleteUserMemoRef, error) {
134		roots, err := queryDeleteUserMemoRefs(ctx, tx, `
135			SELECT id, uid
136			FROM memo
137			WHERE creator_id = `+deleteUserPlaceholder(1), userID)
138		if err != nil {
139			return nil, err
140		}
141	
142		memos := make([]deleteUserMemoRef, 0, len(roots))
143		seen := make(map[int32]struct{})
144		frontier := make([]int32, 0, len(roots))
145		for _, memo := range roots {
146			if _, exists := seen[memo.ID]; exists {
147				continue
148			}
149			seen[memo.ID] = struct{}{}
150			memos = append(memos, memo)
151			frontier = append(frontier, memo.ID)
152		}
153	
154		for len(frontier) > 0 {
155			currentFrontier := frontier
156			nextFrontier := make([]int32, 0)
157			for _, batch := range deleteUserBatches(currentFrontier, deleteUserBatchSize) {
158				clause, args := deleteUserInClause(1, batch)
159				children, err := queryDeleteUserMemoRefs(ctx, tx, `
160					SELECT child.id, child.uid
161					FROM memo child
162					JOIN memo_relation rel ON rel.memo_id = child.id AND rel.type = 'COMMENT'
163					WHERE rel.related_memo_id IN `+clause, args...)
164				if err != nil {
165					return nil, err
166				}
167	
168				for _, child := range children {
169					if _, exists := seen[child.ID]; exists {
170						continue
171					}
172					seen[child.ID] = struct{}{}
173					memos = append(memos, child)
174					nextFrontier = append(nextFrontier, child.ID)
175				}
176			}
177			frontier = nextFrontier
178		}
179	
180		return memos, nil
181	}
182	
183	func queryDeleteUserMemoRefs(ctx context.Context, tx *sql.Tx, query string, args ...any) ([]deleteUserMemoRef, error) {
184		rows, err := tx.QueryContext(ctx, query, args...)
185		if err != nil {
186			return nil, err
187		}
188		defer rows.Close()
189	
190		memos := make([]deleteUserMemoRef, 0)
191		for rows.Next() {
192			var memo deleteUserMemoRef
193			if err := rows.Scan(&memo.ID, &memo.UID); err != nil {
194				return nil, err
195			}
196			memos = append(memos, memo)
197		}
198		if err := rows.Err(); err != nil {
199			return nil, err
200		}
201	
202		return memos, nil
203	}
204	
205	func listDeleteUserAttachments(ctx context.Context, tx *sql.Tx, userID int32, memoIDs []int32) ([]*store.Attachment, error) {
206		attachments := make([]*store.Attachment, 0)
207		seen := make(map[int32]struct{})
208		if err := appendDeleteUserAttachments(ctx, tx, `
209			SELECT
210				id,
211				uid,
212				creator_id,
213				memo_id,
214				storage_type,
215				reference,
216				payload
217			FROM attachment
218			WHERE creator_id = `+deleteUserPlaceholder(1), []any{userID}, seen, &attachments); err != nil {
219			return nil, err
220		}
221	
222		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
223			clause, args := deleteUserInClause(1, batch)
224			if err := appendDeleteUserAttachments(ctx, tx, `
225				SELECT
226					id,
227					uid,
228					creator_id,
229					memo_id,
230					storage_type,
231					reference,
232					payload
233				FROM attachment
234				WHERE memo_id IN `+clause, args, seen, &attachments); err != nil {
235				return nil, err
236			}
237		}
238	
239		return attachments, nil
240	}
241	
242	func appendDeleteUserAttachments(ctx context.Context, tx *sql.Tx, query string, args []any, seen map[int32]struct{}, attachments *[]*store.Attachment) error {
243		rows, err := tx.QueryContext(ctx, query, args...)
244		if err != nil {
245			return err
246		}
247		defer rows.Close()
248	
249		for rows.Next() {
250			attachment := &store.Attachment{}
251			var memoID sql.NullInt32
252			var storageType string
253			var payloadBytes []byte
254			if err := rows.Scan(&attachment.ID, &attachment.UID, &attachment.CreatorID, &memoID, &storageType, &attachment.Reference, &payloadBytes); err != nil {
255				return err
256			}
257			if _, exists := seen[attachment.ID]; exists {
258				continue
259			}
260			seen[attachment.ID] = struct{}{}
261			if memoID.Valid {
262				attachment.MemoID = &memoID.Int32
263			}
264			attachment.StorageType = storepb.AttachmentStorageType(storepb.AttachmentStorageType_value[storageType])
265			payload := &storepb.AttachmentPayload{}
266			if len(payloadBytes) > 0 {
267				if err := protojsonUnmarshaler.Unmarshal(payloadBytes, payload); err != nil {
268					return err
269				}
270			}
271			attachment.Payload = payload
272			*attachments = append(*attachments, attachment)
273		}
274		return rows.Err()
275	}
276	
277	func listDeleteUserSettingKeys(ctx context.Context, tx *sql.Tx, userID int32) ([]storepb.UserSetting_Key, error) {
278		rows, err := tx.QueryContext(ctx, deleteUserSettingKeysQuery(), userID)
279		if err != nil {
280			return nil, err
281		}
282		defer rows.Close()
283	
284		keys := make([]storepb.UserSetting_Key, 0)
285		for rows.Next() {
286			var keyString string
287			if err := rows.Scan(&keyString); err != nil {
288				return nil, err
289			}
290			key := storepb.UserSetting_Key(storepb.UserSetting_Key_value[keyString])
291			keys = append(keys, key)
292		}
293		if err := rows.Err(); err != nil {
294			return nil, err
295		}
296	
297		return keys, nil
298	}
299	
300	func deleteUserSettingKeysQuery() string {
301		return "SELECT `key` FROM `user_setting` WHERE user_id = " + deleteUserPlaceholder(1)
302	}
303	
304	func listDeleteUserInboxIDs(ctx context.Context, tx *sql.Tx, userID int32, memoIDSet map[int32]struct{}) ([]int32, error) {
305		directIDs, err := listDeleteUserDirectInboxIDs(ctx, tx, userID)
306		if err != nil {
307			return nil, err
308		}
309		inboxIDs := append([]int32{}, directIDs...)
310		if len(memoIDSet) == 0 {
311			return inboxIDs, nil
312		}
313	
314		memoIDs, err := listDeleteUserMemoReferencedInboxIDs(ctx, tx, userID, memoIDSet)
315		if err != nil {
316			return nil, err
317		}
318		return append(inboxIDs, memoIDs...), nil
319	}
320	
321	func listDeleteUserDirectInboxIDs(ctx context.Context, tx *sql.Tx, userID int32) ([]int32, error) {
322		rows, err := tx.QueryContext(ctx, `
323			SELECT id
324			FROM inbox
325			WHERE sender_id = `+deleteUserPlaceholder(1)+`
326				OR receiver_id = `+deleteUserPlaceholder(2), userID, userID)
327		if err != nil {
328			return nil, err
329		}
330		defer rows.Close()
331	
332		inboxIDs := make([]int32, 0)
333		for rows.Next() {
334			var inboxID int32
335			if err := rows.Scan(&inboxID); err != nil {
336				return nil, err
337			}
338			inboxIDs = append(inboxIDs, inboxID)
339		}
340		if err := rows.Err(); err != nil {
341			return nil, err
342		}
343	
344		return inboxIDs, nil
345	}
346	
347	func listDeleteUserMemoReferencedInboxIDs(ctx context.Context, tx *sql.Tx, userID int32, memoIDSet map[int32]struct{}) ([]int32, error) {
348		rows, err := tx.QueryContext(ctx, `
349			SELECT id, message
350			FROM inbox
351			WHERE sender_id <> `+deleteUserPlaceholder(1)+`
352				AND receiver_id <> `+deleteUserPlaceholder(2), userID, userID)
353		if err != nil {
354			return nil, err
355		}
356		defer rows.Close()
357	
358		inboxIDs := make([]int32, 0)
359		for rows.Next() {
360			var (
361				inboxID    int32
362				messageRaw []byte
363			)
364			if err := rows.Scan(&inboxID, &messageRaw); err != nil {
365				return nil, err
366			}
367			if len(messageRaw) == 0 {
368				continue
369			}
370	
371			message := &storepb.InboxMessage{}
372			if err := protojsonUnmarshaler.Unmarshal(messageRaw, message); err != nil {
373				return nil, err
374			}
375			if inboxMessageTouchesMemoSet(message, memoIDSet) {
376				inboxIDs = append(inboxIDs, inboxID)
377			}
378		}
379		if err := rows.Err(); err != nil {
380			return nil, err
381		}
382	
383		return inboxIDs, nil
384	}
385	
386	func inboxMessageTouchesMemoSet(message *storepb.InboxMessage, memoIDSet map[int32]struct{}) bool {
387		if message == nil {
388			return false
389		}
390	
391		switch message.Type {
392		case storepb.InboxMessage_MEMO_COMMENT:
393			payload := message.GetMemoComment()
394			if payload == nil {
395				return false
396			}
397			return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
398		case storepb.InboxMessage_MEMO_MENTION:
399			payload := message.GetMemoMention()
400			if payload == nil {
401				return false
402			}
403			return memoIDInSet(payload.MemoId, memoIDSet) || memoIDInSet(payload.RelatedMemoId, memoIDSet)
404		default:
405			return false
406		}
407	}
408	
409	func memoIDInSet(id int32, memoIDSet map[int32]struct{}) bool {
410		if id == 0 {
